package test;

import org.eclipse.jdt.internal.corext.util.Strings;
import org.eclipse.jdt.internal.ui.viewsupport.JavaElementLabelComposer;
import org.eclipse.jface.viewers.StyledString;

public class TestClass {
    public String getLabel(String name) {
        return Strings.markLTR(name, JavaElementLabelComposer.ADDITIONAL_DELIMITERS);
    }

    public String getAnotherLabel(StringBuilder buf) {
        return Strings.markLTR(buf.toString(), JavaElementLabelComposer.ADDITIONAL_DELIMITERS);
    }

    // This method matches the pattern and guard, as StyledString.toString() returns a String.
    public String getStyledStringLabel(StyledString styled) {
        return Strings.markLTR(styled.toString(), JavaElementLabelComposer.ADDITIONAL_DELIMITERS);
    }
}

afterExample:
package test;

import org.eclipse.jdt.internal.corext.util.Strings;

// JavaElementLabelComposer.ADDITIONAL_DELIMITERS is removed and no longer needed.
// Assuming Strings.markJavaElementLabelLTR is available.
import org.eclipse.jface.viewers.StyledString;

public class TestClass {
    public String getLabel(String name) {
        return Strings.markJavaElementLabelLTR(name);
    }

    public String getAnotherLabel(StringBuilder buf) {
        return Strings.markJavaElementLabelLTR(buf.toString());
    }

    // This method's argument is String, so the rule applies safely.
    public String getStyledStringLabel(StyledString styled) {
        return Strings.markJavaElementLabelLTR(styled.toString());
    }
}

