package test;

import org.eclipse.jdt.internal.corext.util.Strings;
import org.eclipse.jdt.internal.ui.viewsupport.JavaElementLabelComposer;
import org.eclipse.jface.viewers.StyledString;

public class NegativeTestClass {

    // Should not match: different second argument (String literal)
    public String getFilePattern(String name) {
        return Strings.markLTR(name, "*.?");
    }

    // Should not match: second argument is a local variable, not the specific constant
    public String getUrlPart(String name, String delimiters) {
        return Strings.markLTR(name, delimiters);
    }

    // Should not match: $x is a StyledString object, not a java.lang.String. The 'instanceof' guard prevents this match.
    // (The `markLTR` method might have an overload for StyledString, but this rule specifically targets String arguments).
    public StyledString getStyledStringArgumentExample(StyledString styledResult) {
        return Strings.markLTR(styledResult, JavaElementLabelComposer.ADDITIONAL_DELIMITERS);
    }
}
